import os,json
S=os.environ['RLM_SESSION_DIR']
t=open(S+'/../../sessions/'+os.path.basename(S)+'.jsonl').read()
# parse demo pair 1
import re
def parse(label,txt):
    m=re.search(label+r' \((\d+)x(\d+)\):\n',txt)
    h,w=int(m[1]),int(m[2])
    return [[int(x) for x in r.split()] for r in txt[m.end():].split('\n')[:h]]
inp=parse('Demo pair 1 input',t); out=parse('Demo pair 1 output',t)
def transform(g):
    from collections import Counter
    c=Counter(x for r in g for x in r); bg=c.most_common(1)[0][0]
    H,W=len(g),len(g[0])
    # find template: contiguous run of non-bg cells (horizontal or vertical)
    tmpl=None; orient=None
    for r in range(H):
        run=[]
        for cc in range(W):
            if g[r][cc]!=bg: run.append((r,cc))
            else:
                if len(run)>=2: tmpl=[g[x[0]][x[1]] for x in run]; orient='h'
                run=[]
        if len(run)>=2: tmpl=[g[x[0]][x[1]] for x in run]; orient='h'
    if tmpl is None:
        for cc in range(W):
            run=[]
            for r in range(H):
                if g[r][cc]!=bg: run.append((r,cc))
                else:
                    if len(run)>=2: tmpl=[g[x[0]][x[1]] for x in run]; orient='v'
                    run=[]
            if len(run)>=2: tmpl=[g[x[0]][x[1]] for x in run]; orient='v'
    o=[[bg]*W for _ in range(H)]
    mid=len(tmpl)//2
    for r in range(H):
        for cc in range(W):
            if g[r][cc]!=bg:
                if orient=='h':
                    if cc-mid>=0 and cc+len(tmpl)-1-mid<W:
                        for i,v in enumerate(tmpl): o[r][cc-mid+i]=v
                else:
                    if r-mid>=0 and r+len(tmpl)-1-mid<H:
                        for i,v in enumerate(tmpl): o[r-mid+i][cc]=v
    return o
